        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(IPlacedObjectGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (FormLinkInformation.TryFactory(obj.GNAM, out var GNAMInfo))
            {
                yield return GNAMInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ISIZ, out var ISIZInfo))
            {
                yield return ISIZInfo;
            }
            if (obj.KWDA is {} KWDAItem)
            {
                foreach (var item in KWDAItem)
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.NAME, out var NAMEInfo))
            {
                yield return NAMEInfo;
            }
            if (FormLinkInformation.TryFactory(obj.SRGN, out var SRGNInfo))
            {
                yield return SRGNInfo;
            }
            if (FormLinkInformation.TryFactory(obj.XACT, out var XACTInfo))
            {
                yield return XACTInfo;
            }
            if (obj.ActivateParents is {} ActivateParentsItems)
            {
                foreach (var item in ActivateParentsItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (FormLinkInformation.TryFactory(obj.XASP, out var XASPInfo))
            {
                yield return XASPInfo;
            }
            if (FormLinkInformation.TryFactory(obj.XATR, out var XATRInfo))
            {
                yield return XATRInfo;
            }
            if (FormLinkInformation.TryFactory(obj.XCNT, out var XCNTInfo))
            {
                yield return XCNTInfo;
            }
